import{_ as i,o as e,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const A=JSON.parse('{"title":"CDS Infernalis (Day 1) -- RGW: Active/Active Arch","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- RGW: Active/Active Arch","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Ceph","RGW","Active","Active 架构","分布式存储","同步机制"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Active_Active_Arch.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Active_Active_Arch.md","lastUpdated":1780459816000}'),s={name:"posts/2015/CDS_Infernalis_Day_1_--_RGW_-_Active_Active_Arch.md"};function n(o,t,_,a,c,g){return e(),l("div",null,[...t[0]||(t[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： RGW（Rados Gateway）的Active-Active架构设计与实现讨论</p><p><strong>参会人员</strong>： Yehuda（会议主持人）、其他研发人员</p><p><strong>会议内容</strong>：</p><p><strong>1. 当前架构概述</strong></p><ul><li>介绍了RGW的多区域、多区域组、区域等概念，以及区域组的灾难恢复机制。</li><li>解释了在多区域环境中，数据分布在主区域和辅助区域，以提高可用性和数据冗余。</li></ul><p><strong>2. Active-Active架构的挑战</strong></p><ul><li><strong>区域概念混淆</strong>： 由于“区域”一词与数据中心相似，建议将“区域”更名为“区域组”，以避免混淆。</li><li><strong>单区域写入问题</strong>： 当前架构下，每个区域组内仅有一个可写入的区域，限制了读写操作的灵活性和性能。</li><li><strong>同步机制</strong>： 需要改进同步机制，确保数据在不同区域组之间的一致性。</li><li><strong>对象版本控制</strong>： 需要改进对象版本控制机制，以支持多区域环境。</li></ul><p><strong>3. 解决方案</strong></p><ul><li><strong>区域组名称变更</strong>： 将“区域”更名为“区域组”，以避免混淆。</li><li><strong>多区域写入</strong>： 支持每个区域组内的多个区域进行读写操作，提高性能和可用性。</li><li><strong>改进同步机制</strong>： <ul><li>每个区域维护自己的日志，以便跟踪其他区域的变化。</li><li>同步代理（Sync Agent）负责同步区域之间的日志，并执行相关命令。</li><li>处理不同区域上的同一对象上的更改冲突。</li></ul></li><li><strong>对象版本控制</strong>： <ul><li>使用计数器和时间戳的组合来替换当前的Epoch方案，以保持对象版本顺序。</li><li>处理同一时间戳上的更改冲突。</li></ul></li></ul><p><strong>4. 其他讨论</strong></p><ul><li>同步代理的改进：需要改进同步代理，使其能够处理多个区域，并支持更复杂的同步策略。</li><li>失败切换：需要改进失败切换机制，以便在切换到辅助区域时保持数据一致性。</li><li>时间同步：需要确保区域组之间的时间同步，以避免时间漂移问题。</li></ul><p><strong>5. 后续行动计划</strong></p><ul><li>进一步完善Active-Active架构的设计方案。</li><li>修改RGW代码，以实现Active-Active架构。</li><li>进行测试，验证Active-Active架构的可行性和性能。</li></ul><p><strong>关键词</strong>： Active-Active架构、区域组、区域、同步、对象版本控制、同步代理、失败切换、时间同步</p>',15)])])}const v=i(s,[["render",n]]);export{A as __pageData,v as default};
